MessagingService:SubscribeAsync.example:
-- Script in ServerScriptService
local MessagingService = game:GetService("MessagingService")

local ok, connection = pcall(function()
	return MessagingService:SubscribeAsync("StartEvent", function(message)
		print("Event starting:", message.Data.name)
	end)
end)

